// The working-tree guard for scripts/check.sh. The checks must read the
// repository without changing it. This guard hashes, before and after:
//   - contents of every file system entry (tracked or not),
//   - the entry type and permission bits,
//   - a symlink's link text, read as bytes, not through the link,
//   - the blob id and mode of every index entry (git ls-files -s),
//   - git's own status view (git status --porcelain).
// A failed read aborts the run: a check that rewrote a file it could not
// read must fail the check, not lose the snapshot entry.
//
// Excluded by policy (one place, this comment): .git, node_modules at any
// depth (reproducible from ci/package-lock.json), and every dot-directory
// except .github (tools' local state; .github holds tracked content). This
// matches the coverage the Dagger mount and the link checker use.
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { readdir, lstat, readFile, readlink } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();

const skipped = (name) => name === "node_modules" || (name.startsWith(".") && name !== ".github");

async function collect(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  const out = [];
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const file = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!skipped(entry.name)) out.push(...(await collect(file)));
      continue;
    }
    const info = await lstat(file);
    const record = [path.relative(root, file), entry.isDirectory() ? "dir" : entry.isFile() ? "file" : entry.isSymbolicLink() ? "link" : "other", info.mode.toString(8), ""];
    if (entry.isSymbolicLink()) record[3] = await readlink(file);
    if (entry.isFile()) {
      const bytes = await readFile(file);
      record[3] = createHash("sha256").update(bytes).digest("hex");
    }
    out.push(record.join("\u0000"));
  }
  return out;
}

function gitHash(args) {
  return createHash("sha256").update(execFileSync("git", args, { cwd: root, maxBuffer: 1 << 24 })).digest("hex");
}

async function snapshot() {
  return JSON.stringify({ root, tree: await collect(root), index: gitHash(["ls-files", "-s"]), status: gitHash(["status", "--porcelain"]) });
}

async function verify(before) {
  const after = await snapshot();
  if (after === before) return;
  const a = JSON.parse(before), b = JSON.parse(after);
  const diffs = [
    ...(a.tree.length === b.tree.length ? [] : [`entry count ${a.tree.length} -> ${b.tree.length}`]),
    ...a.tree.filter((x) => !b.tree.includes(x)).slice(0, 10).map((x) => `removed or changed: ${x.split("\u0000")[0]}`),
    ...b.tree.filter((x) => !a.tree.includes(x)).slice(0, 10).map((x) => `added or changed: ${x.split("\u0000")[0]}`),
    ...(a.index === b.index ? [] : ["git index changed"]),
    ...(a.status === b.status ? [] : ["git status changed"]),
  ];
  throw new Error(`the checks changed the working tree:\n  ${[...new Set(diffs)].join("\n  ")}`);
}

const [, , command, stateFile] = process.argv;
if (!stateFile || (command !== "snapshot" && command !== "verify")) {
  console.error("usage: tree-guard.mjs snapshot|verify <state-file>");
  process.exit(2);
}
try {
  if (command === "snapshot") {
    const state = await snapshot();
    await writeFile(stateFile, state);
  } else {
    await verify(await readFile(stateFile, "utf8"));
  }
} catch (error) {
  console.error(`tree-guard: ${error.message ?? error}`);
  process.exit(1);
}

// Fail-closed check that each decision record's Status agrees with the
// index. Every error condition the project can reach is reported, not
// skipped: a missing or empty index, no record files, duplicate index rows,
// a record with no row, a row with no record, an empty Status on either
// side, a row link that does not resolve to the record it names, and any
// status disagreement. Exports checkDecisions for node:test.
import { readdir, readFile, stat } from "node:fs/promises";
import path from "node:path";

const rowPattern = /^\|\s*\[([A-Za-z0-9-]+)\]\(([^)\s]+)\)\s*\|\s*(.+?)\s*\|\s*(.*?)\s*\|$/

export async function checkDecisions(decisionsDir, indexFile) {
  const errors = [];
  const rows = new Map();
  let indexText = "";
  try {
    indexText = await readFile(indexFile, "utf8");
  } catch (error) {
    errors.push(`cannot read index ${indexFile}: ${error.message}`);
  }
  for (const line of indexText.split("\n").map((l) => l.trim())) {
    const match = rowPattern.exec(line);
    if (!match) continue;
    const [, id, file, title, status] = match;
    if (rows.has(id)) errors.push(`${path.basename(indexFile)}: duplicate row for ${id}`);
    rows.set(id, { file, title, status });
  }
  if (rows.size === 0) errors.push(`${indexFile}: no record rows found`);

  let recordFiles = [];
  try {
    recordFiles = (await readdir(decisionsDir)).filter((f) => /^EPG-DEC-\d{4}[-.]/.test(f));
  } catch (error) {
    errors.push(`cannot read record folder ${decisionsDir}: ${error.message}`);
  }
  if (recordFiles.length === 0) errors.push(`${decisionsDir}: no record files found`);

  const seenRecords = new Set();
  for (const file of recordFiles.sort()) {
    const id = /^([A-Za-z0-9-]+?)-/.exec(file)?.[1] ?? file;
    seenRecords.add(id);
    const recordPath = path.join(decisionsDir, file);
    const row = rows.get(id);
    if (!row) { errors.push(`${file}: no index row for ${id}`); continue; }
    if (row.file !== file) {
      // The row's link must name this record file.
      try {
        await stat(path.join(decisionsDir, row.file));
      } catch {
        errors.push(`${path.basename(indexFile)}: row ${id} links to missing file ${row.file}`);
      }
    }
    let text = "";
    try {
      text = await readFile(recordPath, "utf8");
    } catch (error) {
      errors.push(`cannot read record ${file}: ${error.message}`);
      continue;
    }
    const statusRow = /^\|\s*Status\s*\|\s*([^|]+?)\s*\|/m.exec(text);
    if (!statusRow) { errors.push(`${file}: no Status field`); continue; }
    if (!row.status) errors.push(`${path.basename(indexFile)}: empty Status for ${id}`);
    if (row.status !== statusRow[1]) {
      errors.push(`${file}: Status '${statusRow[1]}' disagrees with index '${row.status}'`);
    }
  }

  for (const [id, row] of rows) {
    if (seenRecords.has(id)) continue;
    const target = path.join(decisionsDir, row.file);
    try {
      await stat(target);
      errors.push(`${row.file}: index row for ${id} has no matching record (file resolves but is ignored by the record pattern)`);
    } catch {
      errors.push(`${path.basename(indexFile)}: index row for ${id} has no record file`);
    }
  }

  return errors;
}

const calledDirectly = process.argv[1] && path.basename(process.argv[1]) === "check-decisions.mjs";
if (calledDirectly) {
  const errors = await checkDecisions(process.argv[2] ?? "docs/decisions", path.join(process.argv[2] ?? "docs/decisions", "INDEX.md"));
  for (const error of errors) console.error(`check-decisions: ${error}`);
  process.exitCode = errors.length ? 1 : 0;
  if (!errors.length) console.log(`check-decisions: ${rows_count_ok}`);
}

